{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C24"],
      "claim": "Brigatinib, a structurally similar anilino-pyrimidine kinase inhibitor with a basic amine side chain, had an absolute oral bioavailability of 46% in healthy volunteers, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Nilotinib, the closest-transfer anilino-pyrimidine analogue, had an absolute oral bioavailability of 31% under fasted conditions in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "At a 400 mg dose, nilotinib absolute bioavailability was 17%, indicating that dose- or solubility-limited absorption can reduce F below 20% in this structural class.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "R101933, a moderately transferable lipophilic basic molecule, showed low oral bioavailability and high interpatient variability, providing some contrary evidence, though it is structurally less similar.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The two highest-transfer analogues are anilino-pyrimidine kinase inhibitors with measured human absolute oral bioavailability of 31% (nilotinib) and 46% (brigatinib), both above the 20% threshold. Lower-transfer low-bioavailability molecules are structurally dissimilar and do not override this class-level evidence. Therefore predict high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is available for the query molecule.",
    "Nilotinib data show dose-dependent bioavailability (17% at 400 mg vs 31% fasted), so dose and formulation effects for the query are uncertain.",
    "Transporter- and solubility-related liabilities are not directly quantified for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

